B = (0,b);
C = (s/2,-sqrt(3)/2*(s - 5));
F[1] = (c,0);
F[2] = (-c,0);
M = (A + C)/2;

draw(yscale(b)*xscale(a)*Circle((0,0),1));
draw(A--B--C--cycle);
draw((-a,0)--(a,0));
draw((0,-b)--(0,b));

label("$P$", A, SW);
label("$Q$", B, N);
label("$R$", C, SE);
dot("$F_1$", F[1], NE);
dot("$F_2$", F[2], NW);
